export type Wan = {
	/** Magic WAN health check rate for tunnels created on this link. The default value is `mid`. */
	health_check_rate?: "low" | "mid" | "high";
	/** Identifier */
	id?: Identifier;
	load_balance_inner_flows?: boolean;
	name?: string;
	physport?: Port;
	/** Priority of WAN for traffic loadbalancing. */
	priority?: number;
	/** Provisioned download rate of the WAN circuit in kilobits per second. */
	provisioned_download_kbps?: number;
	/** Provisioned upload rate of the WAN circuit in kilobits per second. */
	provisioned_upload_kbps?: number;
	/** Identifier */
	site_id?: Identifier;
	/** (optional) if omitted, use DHCP. Submit secondary_address when site is in high availability mode. */
	static_addressing?: WanStaticAddressing;
	/** VLAN ID. Use zero for untagged. */
	vlan_tag?: VlanTag;
};

